<script setup lang="ts">
import { IconChevronLeft, IconChevronRight, IconCode, IconX } from '@tabler/icons-vue'
import JsonTree from '~/components/admin/JsonTree.vue'
import type { RequestLogView } from '#shared/types/hub'
import { extractLogImages, parseLogBodyContent, reconstructLogMessages, reconstructLogRequestMessages } from '#shared/utils/admin-log-view'
import { formatTokenCount } from '#shared/utils/number-format'
definePageMeta({ layout:'console', middleware:'user' })
useSeoMeta({ title:'请求记录 | Zephyr Hub' })
interface BodyView {contentType:string;encoding:string;content:string}
interface Detail extends Record<string,unknown>{requestId:string;requestBody:BodyView|null;responseBody:BodyView|null;requestBodyHash:string|null;responseBodyHash:string|null}
const page=ref(1);const {data,refresh}=await useFetch<{items:RequestLogView[];page:number;pageSize:number;total:number}>('/api/console/logs',{query:computed(()=>({page:page.value,pageSize:50}))});watch(page,()=>refresh())
const maxPage=computed(()=>Math.max(1,Math.ceil((data.value?.total||0)/50)));const detail=ref<Detail|null>(null)
async function open(item:RequestLogView){detail.value=await $fetch<Detail>(`/api/console/logs/${item.id}`)}
function parsed(body:BodyView|null){if(!body||body.encoding==='base64')return null;const result=parseLogBodyContent(body.content,body.contentType);return result.parsed?result.value:null}
const requestJson=computed(()=>parsed(detail.value?.requestBody||null));const responseJson=computed(()=>parsed(detail.value?.responseBody||null));const requestMessages=computed(()=>reconstructLogRequestMessages(requestJson.value));const responseMessages=computed(()=>reconstructLogMessages(responseJson.value));const images=computed(()=>extractLogImages(responseJson.value))
const time=(v:number)=>new Date(v).toLocaleString('zh-CN');const money=(v:number)=>`$${v.toFixed(v<1?6:2)}`
</script>
<template><div class="admin-page admin-page--logs"><header class="admin-page__header"><div><span class="admin-kicker">MY REQUESTS</span><h1>请求记录</h1><p>只显示归属于你的 Key 的调用记录。</p></div></header><section class="admin-table-wrap"><table class="admin-table admin-table--logs"><thead><tr><th>时间 / 请求 ID</th><th>Key</th><th>模型 / 端点</th><th>状态</th><th>Token</th><th>成本</th><th>耗时</th></tr></thead><tbody><tr v-for="item in data?.items||[]" :key="item.id" @click="open(item)"><td><strong>{{ time(item.createdAt) }}</strong><code>{{ item.requestId }}</code></td><td>{{ item.keyName }}</td><td><code>{{ item.requestedModel||'—' }}</code><small>{{ item.endpoint.replace('/v1/','') }}</small></td><td><span class="status-dot" :data-status="item.status"><i />{{ item.httpStatus||'—' }}</span></td><td>{{ formatTokenCount(item.totalTokens) }}</td><td>{{ money(item.cost) }}</td><td>{{ item.durationMs===null?'—':`${item.durationMs}ms` }}</td></tr><tr v-if="!data?.items.length"><td colspan="7"><div class="admin-empty">尚无请求记录</div></td></tr></tbody></table></section><footer class="admin-pagination"><button class="icon-button" :disabled="page<=1" @click="page--"><IconChevronLeft :size="18" /></button><span>第 {{ page }} / {{ maxPage }} 页</span><button class="icon-button" :disabled="page>=maxPage" @click="page++"><IconChevronRight :size="18" /></button></footer><div v-if="detail" class="log-drawer-backdrop" @click.self="detail=null"><aside class="log-drawer"><header><div><span>REQUEST DETAIL</span><code>{{ detail.requestId }}</code></div><button class="icon-button" @click="detail=null"><IconX :size="18" /></button></header><section class="log-body"><header><IconCode :size="17" /><h3>用户输入</h3></header><div v-if="requestMessages.length" class="log-messages"><article v-for="message in requestMessages" :key="message.id"><header><strong>{{ message.label }}</strong></header><pre>{{ message.content }}</pre></article></div><div v-else class="admin-empty">没有可整理的用户文本</div></section><section class="log-body"><header><IconCode :size="17" /><h3>助手响应</h3></header><div v-if="responseMessages.length" class="log-messages"><article v-for="message in responseMessages" :key="message.id"><header><strong>{{ message.label }}</strong></header><pre>{{ message.content }}</pre></article></div><div v-else class="admin-empty">没有可拼接的响应文本</div></section><section class="log-body"><header><h3>原始请求 JSON</h3></header><JsonTree v-if="requestJson!==null" :value="requestJson" /><pre v-else>{{ detail.requestBody?.content||'正文不可用' }}</pre></section><section class="log-body"><header><h3>原始响应 JSON</h3></header><JsonTree v-if="responseJson!==null" :value="responseJson" /><pre v-else>{{ detail.responseBody?.content||'正文不可用' }}</pre><div v-if="images.length" class="log-images"><header><h4>生成图片</h4><span>{{ images.length }} 张</span></header><div><a v-for="(image,index) in images" :key="index" :href="image.src" target="_blank"><img :src="image.src" :alt="`生成图片 ${index+1}`"></a></div></div></section></aside></div></div></template>
